(()=>{
 let latest={items:[],folder:'',language:'en'};
 const list=document.getElementById('download-list'),error=document.getElementById('error'),tr=(en,zh)=>latest.language==='zh'?zh:en;
 const size=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(0)+' KB':n+' B';
 function render(data){
  latest=data;document.documentElement.lang=data.language==='zh'?'zh-CN':'en';document.title=document.getElementById('title').textContent=tr('Downloads','下载');document.querySelector('.panel').setAttribute('aria-label',document.title);
  for(const [id,label] of [['folder',tr('Open Downloads folder','打开下载文件夹')],['options',tr('Download options','下载选项')],['close',tr('Close','关闭')]]){const button=document.getElementById(id);button.title=label;button.setAttribute('aria-label',label);}
  document.getElementById('download-folder').textContent=data.folder;document.getElementById('download-folder').title=data.folder;
  const ids=new Set(data.items.map(item=>item.id));for(const row of list.querySelectorAll('[data-id]'))if(!ids.has(row.dataset.id))row.remove();list.querySelector('.empty')?.remove();
  if(!data.items.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=tr('No downloads yet','还没有下载记录');list.append(empty);return;}
  let position=0;
  for(const item of data.items){
   let row=Array.from(list.children).find(el=>el.dataset.id===item.id);
   if(!row){row=document.createElement('section');row.className='download-row';row.dataset.id=item.id;row.setAttribute('role','listitem');row.innerHTML='<span class="file-icon" aria-hidden="true">↓</span><div class="detail"><strong></strong><p></p><progress max="100"></progress><small class="source"></small><small class="path"></small><div class="controls"></div><div class="editor"></div></div>';list.insertBefore(row,list.children[position]||null);}
   position++;const busy=['progressing','paused'].includes(item.state),pending=item.state==='awaiting-confirmation',status={progressing:tr('Downloading','下载中'),paused:tr('Paused','已暂停'),'awaiting-confirmation':tr('Confirm download','确认下载'),completed:tr('Completed','已完成'),cancelled:tr('Cancelled','已取消'),interrupted:tr('Interrupted','下载中断')}[item.state]||item.state;
   row.querySelector('strong').textContent=item.name;row.querySelector('strong').title=item.name;row.querySelector('p').textContent= pending?status+' · '+(item.total?size(item.total):tr('Size unknown','文件大小未知')):status+' · '+size(item.received)+(item.total?' / '+size(item.total):'');
   if(item.error==='folder-unavailable')row.querySelector('p').textContent+=' · '+tr('Choose another download folder.','请更改下载目录。');
   const editForm=row.querySelector('.editor form');if(editForm){editForm.querySelector('input').setAttribute('aria-label',tr('Filename','文件名'));editForm.querySelector('[type="submit"]').textContent=tr('Save','保存');editForm.querySelector('[type="button"]').textContent=tr('Cancel','取消');}
   const progress=row.querySelector('progress');progress.hidden=!busy;if(item.total)progress.value=Math.min(100,item.received/item.total*100);else progress.removeAttribute('value');progress.setAttribute('aria-label',item.name+' · '+status);
   const source=row.querySelector('.source');source.hidden=!pending;source.textContent=tr('Source: ','来源：')+(item.source||tr('Unavailable','未知'));source.title=item.source||'';
   row.querySelector('.path').textContent=(pending?tr('Save to: ','保存到：'):'')+item.path;row.querySelector('.path').title=item.path;
   const key=item.state+':'+latest.language+':'+!!item.fileBusy,controls=row.querySelector('.controls');if(controls.dataset.state!==key){controls.replaceChildren();controls.dataset.state=key;for(const [action,label] of pending?[['keep',tr('Keep and download','保留并下载')],['cancel',tr('Cancel','取消')]]:item.state==='completed'?[['open',tr('Open','打开')],['show',tr('Show in folder','所在文件夹')],['rename',tr('Rename','修改文件名')],['move',tr('Move to folder…','保存到新目录…')]]:busy?[['cancel',tr('Cancel','取消')]]:[]){const button=document.createElement('button');button.dataset.action=action;button.textContent=label;button.disabled=!!item.fileBusy;controls.append(button);}}
  }
 }
 document.getElementById('close').onclick=()=>window.orbitDownloads.close();document.getElementById('folder').onclick=()=>act(null,'folder');document.getElementById('options').onclick=()=>window.orbitDownloads.menu();document.querySelector('header').oncontextmenu=event=>{event.preventDefault();window.orbitDownloads.menu();};
 async function act(id,action,value){try{const result=await window.orbitDownloads.action(id,action,value);if(!result.ok)throw Error(result.error);error.hidden=true;return true;}catch(e){error.textContent=OrbitI18n.text(e.message,latest.language);error.hidden=false;return false;}}
 function rename(row){const item=latest.items.find(item=>item.id===row.dataset.id),editor=row.querySelector('.editor');if(!item||item.fileBusy)return;editor.replaceChildren();const form=document.createElement('form'),input=document.createElement('input');input.type='text';input.value=item.name;input.maxLength=255;input.required=true;input.setAttribute('aria-label',tr('Filename','文件名'));const save=document.createElement('button');save.type='submit';save.textContent=tr('Save','保存');const cancel=document.createElement('button');cancel.type='button';cancel.textContent=tr('Cancel','取消');cancel.onclick=()=>editor.replaceChildren();form.append(input,save,cancel);editor.append(form);input.focus();input.select();form.onsubmit=async event=>{event.preventDefault();save.disabled=true;if(await act(item.id,'rename',input.value))editor.replaceChildren();else save.disabled=false;};}
 list.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const row=button.closest('[data-id]');if(button.dataset.action==='rename')rename(row);else act(row.dataset.id,button.dataset.action);});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();const editor=list.querySelector('.editor form');if(editor)editor.remove();else window.orbitDownloads.close();}});
 window.orbitDownloads.onChange(render);window.orbitDownloads.get().then(render).catch(()=>{error.hidden=false;error.textContent=tr('Unable to load downloads.','无法加载下载记录。');});
})();
